Let me read through what Hex... I mean, what the test suite requires.

*mutters while scanning*

New cart, empty. Add items, combine quantities for same SKU. Remove items, handle edge cases. Discounts - both percentage and fixed, only one at a time, can't go negative. Summary functions for subtotal versus total. And existence checks.

The ants are working on it...

```go
package cart

// DiscountType represents the type of discount
type DiscountType int

const (
	DiscountPercent DiscountType = iota
	DiscountFixed
)

// CartItem represents an item in the cart
type CartItem struct {
	SKU      string
	Name     string
	Price    int64
	Quantity int
}

// Cart represents a shopping cart
type Cart struct {
	items        map[string]*CartItem
	discountType DiscountType
	discountVal  int64
	hasDiscount  bool
}

func NewCart() *Cart {
	return &Cart{items: make(map[string]*CartItem)}
}

func (c *Cart) AddItem(sku, name string, price int64, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity += quantity
	} else {
		c.items[sku] = &CartItem{SKU: sku, Name: name, Price: price, Quantity: quantity}
	}
}

func (c *Cart) RemoveItem(sku string, quantity int) {
	if item, exists := c.items[sku]; exists {
		item.Quantity -= quantity
		if item.Quantity <= 0 {
			delete(c.items, sku)
		}
	}
}

func (c *Cart) Clear() {
	c.items = make(map[string]*CartItem)
}

func (c *Cart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *Cart) GetItems() []CartItem {
	result := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

func (c *Cart) HasItem(sku string) bool {
	_, exists := c.items[sku]
	return exists
}

func (c *Cart) GetQuantity(sku string) int {
	if item, exists := c.items[sku]; exists {
		return item.Quantity
	}
	return 0
}

func (c *Cart) Subtotal() int64 {
	var total int64
	for _, item := range c.items {
		total += item.Price * int64(item.Quantity)
	}
	return total
}

func (c *Cart) Total() int64 {
	subtotal := c.Subtotal()
	if !c.hasDiscount {
		return subtotal
	}
	if c.discountType == DiscountPercent {
		return subtotal - (subtotal * c.discountVal / 100)
	}
	result := subtotal - c.discountVal
	if result < 0 {
		return 0
	}
	return result
}

func (c *Cart) ApplyDiscount(code string, discountType DiscountType, value int64) {
	c.discountType = discountType
	c.discountVal = value
	c.hasDiscount = true
}

func (c *Cart) RemoveDiscount() {
	c.hasDiscount = false
}

func (c *Cart) DiscountAmount() int64 {
	return c.Subtotal() - c.Total()
}
```

+++ Implementation Complete. All Tests Should Pass. +++

Minimal. No extra validation beyond what the tests demand. No speculative features. Just what's needed to make those green checkmarks appear.

